  '',
  'about',
  'services',
  'contact',
  'how-it-works',
  'service-areas',
  'services/countries-we-source-from',
  'booking',
  'careers',
  'pricing',
  'blog'
];

const trustRoutes = [
  'faq',
  'documents-required',
  'inaya-advantages',
  'reviews',
  'privacy-policy',
  'terms',
  'refund-policy',
  'service-guidelines',
  'support-process'
];

function localizedEntry(path: string, priority: number, changeFrequency: MetadataRoute.Sitemap[number]['changeFrequency'] = 'weekly') {
  return locales.map((locale) => {
    return {
      url: localizedUrl(locale, path),
      ...(contentUpdatedAt[path] ? { lastModified: contentUpdatedAt[path] } : {}),
      changeFrequency,
      priority,
      alternates: {
        languages: {
          ...localeAlternates(locale, path).languages
        }
      }
    };
  });
}

export default function sitemap(): MetadataRoute.Sitemap {
  const corePages = coreRoutes.flatMap((route) => localizedEntry(route, route === '' ? 1 : 0.85));
  const trustPages = trustRoutes.flatMap((route) => localizedEntry(route, 0.72, 'monthly'));

  const servicePages = allServices.flatMap((service) => (
    localizedEntry(`services/${service.slug}`, service.slug === 'countries-we-source-from' ? 0.9 : 0.86)
  ));

  const countryPages = countrySourcePages.flatMap((country) => (
    localizedEntry(`maid-source-countries/${country.slug}`, 0.78)
  ));

  const locationPages = locationServicePages.flatMap((location) => (
    localizedEntry(location.slug, 0.82)
  ));

  const guidePages = domesticWorkerGuides.filter(guide => !keywordArticleSlugs.has(guide.slug) && !newArticleSlugs.has(guide.slug)).flatMap((guide) => (
    localizedEntry(`blog/${guide.slug}`, 0.76, 'monthly')
  ));

  const uniqueEntries = new Map<string, MetadataRoute.Sitemap[number]>();
  const keywordPages = keywordArticleMetadata.flatMap(article => localizedEntry(`blog/${article.slug}`, 0.76, 'monthly'));
  const archivePages = blogArchiveRoutes.flatMap(route => localizedEntry(route, 0.6, 'monthly'));
  const newArticlePages = newArticleMetadata.flatMap(article => localizedEntry(`blog/${article.slug}`, 0.76, 'monthly'));

  for (const entry of [...corePages, ...trustPages, ...servicePages, ...countryPages, ...locationPages, ...guidePages, ...localizedEntry('gallery', 0.65, 'monthly'), ...localizedEntry(companyInformation.route, 0.72, 'monthly'), ...keywordPages, ...archivePages, ...newArticlePages]) {
    uniqueEntries.set(entry.url, entry);
  }

  return Array.from(uniqueEntries.values());
}

