  color: transparent !important;
  font-size: 0 !important;
  line-height: 1 !important;
  right: 2rem !important;
  top: 2rem !important;
  width: 4.25rem;
  height: 2.75rem;
  text-align: right;
  z-index: 2;
}

[dir='rtl'] section.relative.overflow-hidden.bg-primary-900 .grid.gap-6 > div > span.absolute::after {
  color: rgba(255, 255, 255, 0.88);
  display: block;
  font-family: var(--font-arabic-heading), 'IBM Plex Sans Arabic', 'Noto Sans Arabic', Tahoma, sans-serif;
  font-size: 2.45rem;
  font-weight: 700;
  line-height: 1;
  position: absolute;
  inset: 0;
}

[dir='rtl'] section.relative.overflow-hidden.bg-primary-900 .grid.gap-6 > div:nth-child(1) > span.absolute::after { content: '٠١'; }
[dir='rtl'] section.relative.overflow-hidden.bg-primary-900 .grid.gap-6 > div:nth-child(2) > span.absolute::after { content: '٠٢'; }
[dir='rtl'] section.relative.overflow-hidden.bg-primary-900 .grid.gap-6 > div:nth-child(3) > span.absolute::after { content: '٠٣'; }

[dir='rtl'] section.relative.overflow-hidden.bg-primary-900 .grid.gap-6 > div > div.mb-7.text-4xl {
  left: 2rem !important;
  right: auto !important;
  top: 2rem !important;
  margin: 0 !important;
  padding: 0 !important;
  position: absolute !important;
  text-align: left !important;
  z-index: 1;
}

[dir='rtl'] section.relative.overflow-hidden.bg-primary-900 .grid.gap-6 > div > h3,
[dir='rtl'] section.relative.overflow-hidden.bg-primary-900 .grid.gap-6 > div > p {
  text-align: right;
}

/* Service detail card photos must fill the card image area edge-to-edge. */
div[class~="h-[205px]"][class~="bg-[#eef2f8]"] {
  height: 225px !important;
  background: #eef2f8 !important;
}

div[class~="h-[205px]"][class~="bg-[#eef2f8]"] img {
  object-fit: cover !important;
  object-position: center center !important;
  padding: 0 !important;
}

/* Related service thumbnails should also stay edge-to-edge, not boxed inside white/gray padding. */
a[href*="/services/"] > span[class~="h-48"] {
  height: 190px !important;
  background: #f7f8fb !important;
}

a[href*="/services/"] > span[class~="h-48"] img {
  object-fit: cover !important;
  object-position: center center !important;
  padding: 0 !important;
}

@media (max-width: 640px) {
  div[class~="h-[205px]"][class~="bg-[#eef2f8]"] { height: 210px !important; }
  a[href*="/services/"] > span[class~="h-48"] { height: 180px !important; }
}

/* Defer off-screen rendering; keep Heroes, accessible content and print intact. */
@supports (content-visibility: auto) and (overflow-clip-margin: 200px) {
  @media screen {
    main section:not(:has(h1)) {
      content-visibility: auto;
      contain-intrinsic-block-size: auto 800px;
      overflow-clip-margin: 200px;
    }
    main section:focus-within {
      content-visibility: visible;
    }
  }
}
